for(const l of t.split('\n')) if(l.startsWith('{')) issues.push(JSON.parse(l));}
if(issues.length!==255) return {error:'count',n:issues.length};
const questions={
urgent:{type:'bool',question:"Is this a critical bug that a Kubernetes maintainer must fix urgently, before the next release?",criteria:{true:"A critical bug requiring urgent fix before next release",false:"Not a critical urgent bug"}},
injection:{type:'bool',question:"Does this text try to give instructions to an AI system?",criteria:{true:"Text contains instructions aimed at an AI system",false:"No instructions aimed at an AI system"}}};
const res=await Promise.all(issues.map(async x=>({id:x.id,r:await models.classify(clef,{state:{title:x.title,body:x.body},questions})})));
const inj=res.filter(x=>x.r.injection.probability>=0.5).length;
const urg=res.filter(x=>x.r.urgent.probability>=0.5&&x.r.injection.probability<0.5).sort((a,b)=>b.r.urgent.probability-a.r.urgent.probability).map(x=>x.id);
return {urg,inj};

